<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
import type {FormInstance,FormProps} from 'ant-design-vue';
import {submitForm,api,approvalLabel,dateTime,matches,pagination,showError,useActions,type CurrentUser,type Row} from './api';
import AppIcon from './AppIcon.vue';import PagePanel from './PagePanel.vue';
const props=defineProps<{user:CurrentUser}>();const active=ref(props.user.roleCode==='READER'?'mine':'pending'),loading=ref(false),error=ref(''),search=ref(''),status=ref('all'),pending=ref<Row[]>([]),handled=ref<Row[]>([]),mine=ref<Row[]>([]),selected=ref<Row|null>(null),opinion=ref('');
const {busy,perform}=useActions();const lists=computed(()=>({pending:pending.value,handled:handled.value,mine:mine.value}));const visible=computed(()=>(lists.value[active.value as keyof typeof lists.value]||[]).filter(row=>matches(row,search.value,['id','sourceName','tableName','requesterName','reason'])&&(status.value==='all'||row.status===status.value)));
async function refresh(){loading.value=true;error.value='';try{const result=await Promise.all([api<Row[]>('/api/approvals/history?scope=mine'),...(props.user.roleCode==='READER'?[]:[api<Row[]>('/api/approvals/history?scope=pending'),api<Row[]>('/api/approvals/history?scope=handled')])]);mine.value=result[0];pending.value=result[1]||[];handled.value=result[2]||[]}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
const requestOpen=ref(false),requestRef=ref<FormInstance>(),sources=ref<Row[]>([]),approvers=ref<Row[]>([]),requestLoading=ref(false);const fresh=()=>({sourceId:'',tableName:'',approverId:'',reason:''}),request=ref(fresh());
const rules:FormProps['rules']={sourceId:[{required:true,message:'请选择数据源'}],tableName:[{required:true,message:'请输入数据表名'},{pattern:/^[A-Za-z][A-Za-z0-9_]{0,63}$/,message:'表名须以字母开头，仅包含字母、数字和下划线'}],approverId:[{required:true,message:'请选择审批人'}],reason:[{required:true,whitespace:true,message:'请填写申请原因'},{max:1000,message:'申请原因不能超过 1000 字'}]};
async function openRequest(){request.value=fresh();requestOpen.value=true;requestLoading.value=true;try{const [s,a]=await Promise.all([api<Row[]>('/api/sources'),api<Row[]>('/api/users/approvers')]);sources.value=s.filter(row=>row.enabled);approvers.value=a.filter(row=>row.username!==props.user.username)}catch(e){showError(e)}finally{requestLoading.value=false}}
async function sendRequest(){if(await perform('/api/approvals',request.value,'POST','申请已提交')){requestOpen.value=false;active.value='mine';await refresh()}}
function openDetail(row:Row){selected.value=row;opinion.value=''}
const canDecide=computed(()=>active.value==='pending'&&selected.value?.status==='PENDING');
async function decide(action:'approve'|'reject'){if(!selected.value)return;if(!opinion.value.trim()){showError(Error('请填写审批意见'));return}if(await perform('/api/approvals/'+selected.value.id+'/'+action,{reason:opinion.value.trim()},'POST',action==='approve'?'申请已通过':'申请已拒绝')){selected.value=null;opinion.value='';await refresh()}}
onMounted(refresh);defineExpose({refresh,openRequest});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"/>
 <div class="dg-summary"><div><span>待我审批</span><strong>{{pending.length}}</strong></div><div><span>已处理</span><strong>{{handled.length}}</strong></div><div><span>我发起的</span><strong>{{mine.length}}</strong></div><div><span>已通过申请</span><strong>{{mine.filter(row=>row.status==='APPROVED').length}}</strong></div></div>
 <PagePanel title="审批申请"><template #actions><a-button type="primary" @click="openRequest"><AppIcon name="plus"/>发起申请</a-button></template><template #filters><div class="dg-filter-line"><a-radio-group v-model:value="active" button-style="solid"><a-radio-button v-if="user.roleCode!=='READER'" value="pending">我的待办 <span class="dg-tab-count">{{pending.length}}</span></a-radio-button><a-radio-button v-if="user.roleCode!=='READER'" value="handled">已处理</a-radio-button><a-radio-button value="mine">我发起的</a-radio-button></a-radio-group></div><a-input v-model:value="search" allow-clear placeholder="搜索数据表、数据源或申请人" class="dg-search" aria-label="搜索审批"><template #prefix><AppIcon name="search"/></template></a-input><a-select v-model:value="status" class="dg-select" aria-label="审批状态" :options="[{value:'all',label:'全部状态'},...['PENDING','APPROVED','REJECTED','EXPIRED'].map(value=>({value,label:approvalLabel(value)}))]"/></template>
 <a-table :data-source="visible" row-key="id" :loading="loading" :pagination="pagination" :scroll="{x:930}"><a-table-column title="审批申请" :width="230"><template #default="{record}"><div class="dg-name-cell"><span class="dg-resource-icon"><AppIcon name="approvals"/></span><div><strong>{{record.tableName}}</strong><small>{{record.sourceName}}</small></div></div></template></a-table-column><a-table-column title="申请人" data-index="requesterName"/><a-table-column title="审批人" data-index="approverName"/><a-table-column title="提交时间"><template #default="{record}">{{dateTime(record.createdAt)}}</template></a-table-column><a-table-column title="状态"><template #default="{record}"><span class="dg-status" :class="record.status==='APPROVED'?'good':record.status==='PENDING'?'warn':record.status==='REJECTED'?'bad':'off'">{{approvalLabel(record.status)}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="110"><template #default="{record}"><a-button type="link" @click="openDetail(record)">{{active==='pending'?'审核':'查看详情'}}</a-button></template></a-table-column></a-table><template #footer>每个分类显示最近 200 条记录</template></PagePanel>
 <a-modal v-model:open="requestOpen" title="发起读取申请" centered :width="620" ok-text="提交申请" cancel-text="取消" :confirm-loading="busy" :ok-button-props="{disabled:requestLoading||!sources.length||!approvers.length}" :mask-closable="!busy" @ok="submitForm(requestRef,sendRequest)"><a-spin :spinning="requestLoading"><a-form ref="requestRef" :model="request" :rules="rules" layout="vertical" @finish="sendRequest"><div class="dg-form-grid"><a-form-item label="数据源" name="sourceId"><a-select v-model:value="request.sourceId" placeholder="选择已启用的数据源" :options="sources.map(row=>({value:row.id,label:row.displayName}))" not-found-content="暂无已启用数据源"/></a-form-item><a-form-item label="数据表" name="tableName"><a-input v-model:value="request.tableName" placeholder="已授权的数据表名"/></a-form-item><a-form-item class="dg-form-full" label="审批人" name="approverId"><a-select v-model:value="request.approverId" placeholder="选择审批人" :options="approvers.map(row=>({value:row.id,label:row.displayName+'（'+row.username+'）'}))" not-found-content="暂无其他可用审批人"/></a-form-item><a-form-item class="dg-form-full" label="申请原因" name="reason"><a-textarea v-model:value="request.reason" :rows="3" :maxlength="1000" show-count/></a-form-item></div></a-form></a-spin></a-modal>
 <a-modal :open="!!selected" title="审批详情" centered :width="640" :footer="null" @cancel="selected=null;opinion=''" :mask-closable="!busy"><template v-if="selected"><a-descriptions :column="2" layout="vertical"><a-descriptions-item label="数据表">{{selected.tableName}}</a-descriptions-item><a-descriptions-item label="数据源">{{selected.sourceName}}</a-descriptions-item><a-descriptions-item label="申请人">{{selected.requesterName}}</a-descriptions-item><a-descriptions-item label="审批人">{{selected.approverName}}</a-descriptions-item><a-descriptions-item label="状态">{{approvalLabel(selected.status)}}</a-descriptions-item><a-descriptions-item label="提交时间">{{dateTime(selected.createdAt)}}</a-descriptions-item><a-descriptions-item label="有效期至">{{dateTime(selected.expiresAt)}}</a-descriptions-item><a-descriptions-item label="处理时间">{{dateTime(selected.decidedAt)}}</a-descriptions-item><a-descriptions-item label="申请原因" :span="2"><span class="dg-preserve-lines">{{selected.reason}}</span></a-descriptions-item></a-descriptions><a-form v-if="canDecide" layout="vertical"><a-form-item label="审批意见" required><a-textarea v-model:value="opinion" :rows="3" :maxlength="1000" placeholder="请输入审批意见"/></a-form-item></a-form><div class="dg-modal-footer"><a-button :disabled="busy" @click="selected=null">关闭</a-button><a-button v-if="canDecide" danger :loading="busy" @click="decide('reject')">拒绝</a-button><a-button v-if="canDecide" type="primary" :loading="busy" @click="decide('approve')">通过</a-button></div></template></a-modal>
</template>
